<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/foundations/_lib/model.php';
const GORIGIN='https://beyondspacetime.org';
function gdata(string $file):array {static $cache=[];return $cache[$file]??=json_decode(file_get_contents(__DIR__.'/'.$file.'.json'),true,512,JSON_THROW_ON_ERROR);}
function gu(string $lang):array{return gdata('ui')[$lang]??throw new InvalidArgumentException('Unknown language');}
function glessons(string $lang):array{return array_column(gdata('translations')[$lang]??throw new InvalidArgumentException('Unknown language'),null,'id');}
function gh($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function gj($v):string{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR);}
function gp(string $lang,string $id=''):string{return '/global/'.$lang.'/'.($id!==''?$id.'/':'');}
function gn(float|int $v):string{return $v!=0&&(abs($v)<.0001||abs($v)>=1e7)?sprintf('%.4e',$v):rtrim(rtrim(sprintf('%.7f',$v),'0'),'.');}
function gheaders():void{header_remove('X-Powered-By');if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin');header('X-Frame-Options: DENY');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-src 'none'; frame-ancestors 'none'; form-action 'self'");header('Permissions-Policy: camera=(), microphone=(), geolocation=()');}
function gstart(string $lang,string $id,string $title,string $desc,bool $post=false,bool $hub=false):void{$u=gu($lang);gheaders();if($post){header('X-Robots-Tag: noindex');header('Cache-Control: no-store');}$path=$hub?'/global/':gp($lang,$id);$url=GORIGIN.$path;$graph=['@context'=>'https://schema.org','@type'=>$id!==''&&$id!=='glossary'?'LearningResource':'CollectionPage','name'=>$title,'description'=>$desc,'url'=>$url,'inLanguage'=>$lang,'isAccessibleForFree'=>true];if(isset(glessons($lang)[$id])){$l=glessons($lang)[$id];$graph['isBasedOn']=$l['englishUrl'];$graph['educationalUse']='instruction';$graph['learningResourceType']='Interactive lesson';}?>
<!doctype html><html lang="<?=gh($lang)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=gh($title)?> | Beyond Spacetime</title><meta name="description" content="<?=gh($desc)?>"><meta name="robots" content="<?=$post?'noindex, follow':'index, follow'?>"><link rel="canonical" href="<?=gh($url)?>"><?php if(!$hub):foreach(gdata('ui') as $code=>$labels):?><link rel="alternate" hreflang="<?=$code?>" href="<?=GORIGIN.gp($code,$id)?>"><?php endforeach;?><link rel="alternate" hreflang="x-default" href="<?=GORIGIN.gp('en',$id)?>"><?php endif;?><meta property="og:title" content="<?=gh($title)?>"><meta property="og:description" content="<?=gh($desc)?>"><meta property="og:url" content="<?=gh($url)?>"><meta property="og:locale" content="<?=gh($u['locale'])?>"><meta property="og:image" content="<?=GORIGIN?>/foundations/assets/banner.webp"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/research/assets/research.css"><link rel="stylesheet" href="/global/assets/global.css?v=1.8.0"><script type="application/ld+json"><?=gj($graph)?></script><script src="/global/assets/global.js?v=1.8.0" defer></script><link rel="stylesheet" href="/museum/assets/crossnav.css?v=2.0.0"></head><body><a class="skip" href="#main"><?=gh($u['skip'])?></a><header><div class="nav"><a href="/global/" class="brand"><img src="/foundations/assets/compass.png" width="48" height="48" alt=""><span>BEYOND<span class="gold">SPACETIME</span><small><?=gh($u['nav'])?></small></span></a><nav aria-label="<?=gh($u['language'])?>" class="languages"><?php foreach(gdata('ui') as $code=>$labels):?><a lang="<?=$code?>" hreflang="<?=$code?>" href="<?=gp($code,$id)?>" <?=$code===$lang&&!$hub?'aria-current="page"':''?>><?=gh($labels['name'])?></a><?php endforeach;?></nav><a class="arc" href="/"> <?=gh($u['home'])?> ↗</a></div></header><nav class="museum-crossnav" aria-label="Museum exhibits"><a href="/museum/">Museum</a><a href="/museum/search/">Search</a><a href="/foundations/">Foundations</a><a href="/evidence/">Evidence</a><a href="/research/">Workspace</a><a href="/model-comparison/">Compare</a><a href="/timeline/">Timeline</a><a href="/global/" aria-current="true">Languages</a><a href="/offline/">Offline</a><a href="/visualizations/">Visualize</a><a href="/knowledge-graph/">Graph</a><a href="/experiment-design/">Design</a><a href="/universal-time/">Time</a></nav><main id="main" class="wrap"><div class="crumb"><a href="/global/">Global</a> / <a href="<?=gp($lang)?>"><?=gh($u['name'])?></a><?php if($id!==''):?> / <?=gh($title)?><?php endif;?></div><?php }
function gend(string $lang):void{$u=gu($lang);?><footer><div><strong>Beyond Spacetime</strong><p><?=gh($u['notice'])?></p></div><div><a href="<?=gp($lang)?>"><?=gh($u['all'])?></a><br><a href="<?=gp($lang,'glossary')?>"><?=gh($u['glossary'])?></a></div><div><a href="https://arcsecs.com/read-scientific-paper/" hreflang="en"><?=gh($u['source'])?> ↗</a><br><a href="/global/catalog.json">JSON</a> · <a href="/global/sitemap.xml">Sitemap</a></div></footer></main></body></html><?php }
function gsolve(string $lang,string $id,array $params=[]):array{$l=glessons($lang)[$id]??throw new InvalidArgumentException('Unknown lesson');$r=solve($id,$params);return ['schema'=>'beyondspacetime.localized-foundation.v1','version'=>'1.8.0','language'=>$lang,'lesson'=>$id,'original_result'=>$r,'display'=>['xLabel'=>$l['xLabel'],'series'=>$l['series'],'metrics'=>array_map(fn($m,$i)=>['label'=>$l['metrics'][$i],'value'=>$m['value'],'unit'=>$m['unit']],$r['metrics'],array_keys($r['metrics'])),'limitation'=>$l['limitation']],'source'=>$l['source'],'english_url'=>$l['englishUrl']];}
function gchart(array $r):void{$rows=$r['original_result']['rows'];$series=$r['display']['series'];$xmin=min(array_column($rows,0));$xmax=max(array_column($rows,0));$ymin=0;$ymax=0;foreach($rows as $row)foreach(array_slice($row,1) as $v){$ymin=min($ymin,$v);$ymax=max($ymax,$v);}if($xmax===$xmin)$xmax++;if($ymin===$ymax)$ymax++;$x=fn($v)=>65+($v-$xmin)/($xmax-$xmin)*615;$y=fn($v)=>240-($v-$ymin)/($ymax-$ymin)*200;?><figure class="gchart"><svg viewBox="0 0 710 288" role="img" aria-label="<?=gh($r['display']['xLabel'].' — '.implode(', ',$series))?>"><?php for($i=0;$i<=4;$i++):$Y=40+$i*50;$X=65+$i*153.75;?><line x1="65" y1="<?=$Y?>" x2="680" y2="<?=$Y?>" class="g-grid"/><text x="59" y="<?=$Y+4?>" text-anchor="end"><?=gh(gn($ymax-($ymax-$ymin)*$i/4))?></text><text x="<?=$X?>" y="260" text-anchor="middle"><?=gh(gn($xmin+($xmax-$xmin)*$i/4))?></text><?php endfor;foreach($series as $i=>$s):?><polyline class="g-series g-series-<?=$i?>" points="<?=implode(' ',array_map(fn($row)=>sprintf('%.2f,%.2f',$x($row[0]),$y($row[$i+1])),$rows))?>"/><?php endforeach;?><text x="370" y="282" text-anchor="middle"><?=gh($r['display']['xLabel'])?></text></svg><figcaption><?php foreach($series as $i=>$s):?><span><i class="g-swatch g-series-<?=$i?>"></i><?=gh($s)?></span><?php endforeach;?></figcaption></figure><?php }
function gresults(array $r,array $u):void{?><div class="gmetrics"><?php foreach($r['display']['metrics'] as $m):?><div><span><?=gh($m['label'])?></span><strong><?=gh(gn($m['value']))?> <small><?=gh($m['unit'])?></small></strong></div><?php endforeach;?></div><?php gchart($r);?><details><summary><?=gh($u['samples'])?> (<?=count($r['original_result']['rows'])?>)</summary><div class="gtable"><table><thead><tr><th scope="col"><?=gh($r['display']['xLabel'])?></th><?php foreach($r['display']['series'] as $s):?><th scope="col"><?=gh($s)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($r['original_result']['rows'] as $row):?><tr><?php foreach($row as $v):?><td><?=gh(gn($v))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></details><?php }
function gpage(string $lang='en',string $id='',bool $hub=false):void{$u=gu($lang);$method=$_SERVER['REQUEST_METHOD']??'GET';$lesson=glessons($lang)[$id]??null;if(!in_array($method,$lesson?['GET','HEAD','POST']:['GET','HEAD'],true)){gheaders();http_response_code(405);header('Allow: '.($lesson?'GET, HEAD, POST':'GET, HEAD'));return;}
if($hub){gstart('en','','Global scientific education','Choose English, Español or Français. Explore the same twelve research foundations in three languages.',false,true);?><section class="ghero"><img src="/foundations/assets/banner.webp" alt="Beyond Spacetime" width="1400" height="600"><div><span class="eyebrow gold">GLOBAL SCIENTIFIC EDUCATION · 1.8.0</span><h1>One universe.<br>Three languages.</h1><p class="lead">Learn the twelve foundations in your language. The original research remains on ArcSecs.com.</p></div></section><div class="gcards"><?php foreach(gdata('ui') as $c=>$v):?><article class="panel" lang="<?=$c?>"><span class="eyebrow"><?=strtoupper($c)?> · 12</span><h2><?=gh($v['name'])?></h2><p><?=gh($v['description'])?></p><a class="button" href="<?=gp($c)?>"><?=gh($v['all'])?> →</a></article><?php endforeach;?></div><section class="panel gsection"><h2>Shared science, localized explanations</h2><p>All language versions run the same existing foundation solver. The translated charter is displayed with its exact English source statement; no translated publication is asserted. No automatic redirects or external translation service.</p><a href="/foundations/">Original English foundation center →</a> · <a href="/research/">Research workspace →</a></section><?php gend('en');return;}
if($id===''){gstart($lang,'',$u['title'],$u['description']);?><section class="ghero"><img src="/foundations/assets/banner.webp" alt="Beyond Spacetime" width="1400" height="600"><div><span class="eyebrow gold"><?=gh($u['nav'])?> · 12</span><h1><?=gh($u['title'])?></h1><p class="lead"><?=gh($u['intro'])?></p><a class="button" href="<?=gp($lang,'glossary')?>"><?=gh($u['glossary'])?> →</a></div></section><p class="notice"><?=gh($u['notice'])?></p><div class="gcards"><?php foreach(glessons($lang) as $l):?><article class="panel"><span class="eyebrow"><?=str_pad((string)$l['number'],2,'0',STR_PAD_LEFT)?> · <?=gh($u['model'])?></span><h2><a href="<?=gp($lang,$l['id'])?>"><?=gh($l['title'])?></a></h2><p><?=gh($l['answer'])?></p><a class="text-link" href="<?=gp($lang,$l['id'])?>"><?=gh($u['lab'])?> →</a></article><?php endforeach;?></div><?php gend($lang);return;}
if($id==='glossary'){gstart($lang,$id,$u['glossaryTitle'],$u['glossaryDesc']);?><section class="intro"><span class="eyebrow"><?=gh($u['glossary'])?></span><h1><?=gh($u['glossaryTitle'])?></h1><p class="lead"><?=gh($u['glossaryDesc'])?></p></section><div class="gcards two"><?php foreach(gdata('glossary')[$lang] as $term):?><article class="panel"><h2><?=gh($term['term'])?></h2><p><?=gh($term['definition'])?></p><a href="<?=gp($lang,$term['lesson'])?>"><?=gh(glessons($lang)[$term['lesson']]['title'])?> →</a></article><?php endforeach;?></div><?php gend($lang);return;}
if(!$lesson){gheaders();http_response_code(404);return;}$error=false;try{$params=$method==='POST'?($_POST['p']??null):[];if(!is_array($params))throw new InvalidArgumentException();$r=gsolve($lang,$id,$params);}catch(InvalidArgumentException $e){$error=true;http_response_code(422);$r=gsolve($lang,$id);}$src=lessons()[$id];gstart($lang,$id,$lesson['title'],$lesson['answer'],$method==='POST');?><section class="intro"><span class="eyebrow gold"><?=str_pad((string)$lesson['number'],2,'0',STR_PAD_LEFT)?> / 12 · <?=gh($u['model'])?></span><h1><?=gh($lesson['title'])?></h1><p class="lead"><?=gh($lesson['answer'])?></p><p class="muted"><?=gh($u['status'])?></p></section><section class="panel g-premise"><h2><?=gh($u['premise'])?></h2><p class="premise-text"><?=gh($lesson['statement'])?></p><?php if($lang!=='en'):?><p class="muted"><?=gh($u['original'])?>: <span lang="en"><?=gh($src['statement'])?></span></p><?php endif;?><p><?=gh($u['notice'])?></p></section><div class="gcards two gsection"><article class="panel"><h2><?=gh($u['context'])?></h2><p><?=gh($lesson['context'])?></p></article><article class="panel"><h2><?=gh($u['test'])?></h2><p><?=gh($lesson['test'])?></p></article></div><section class="gsection"><h2><?=gh($u['lab'])?></h2><p class="gformula"><?=gh($src['equation'])?></p><div class="glab"><section class="panel"><h3><?=gh($u['params'])?></h3><form method="post" action="<?=gp($lang,$id)?>" id="gform"><?php foreach($src['params'] as $p):?><label for="p-<?=gh($p['key'])?>"><?=gh($lesson['parameters'][$p['key']])?> <?=gh($p['unit'])?></label><input required type="number" step="any" id="p-<?=gh($p['key'])?>" name="p[<?=gh($p['key'])?>]" min="<?=gh($p['min'])?>" max="<?=gh($p['max'])?>" value="<?=gh($r['original_result']['parameters'][$p['key']])?>"><small><?=gh($u['range'])?>: <?=gh($p['min'])?> – <?=gh($p['max'])?></small><?php endforeach;?><button type="submit"><?=gh($u['run'])?></button> <a class="button secondary" href="<?=gp($lang,$id)?>"><?=gh($u['reset'])?></a></form><p class="muted"><?=gh($u['nojs'])?></p><?php if($error):?><p class="notice" role="alert"><?=gh($u['invalid'])?></p><?php endif;?></section><section class="panel"><h3><?=gh($u['results'])?></h3><?php gresults($r,$u);?><button type="button" class="secondary" id="gexport" hidden><?=gh($u['export'])?></button><script type="application/json" id="gresult"><?=gj($r)?></script></section></div></section><section class="panel gsection"><h2><?=gh($u['limit'])?></h2><p><?=gh($lesson['limitation'])?></p><h2><?=gh($u['reference'])?></h2><p><a href="<?=gh($lesson['englishUrl'])?>" hreflang="en"><?=gh($u['english'])?> ↗</a> · <a href="<?=gh($lesson['source']['url'])?>" hreflang="en"><?=gh($u['source'])?> ↗</a></p><p lang="en"><?=gh($lesson['source']['section'])?></p></section><nav class="gsteps" aria-label="<?=gh($u['lessons'])?>"><?php $all=array_values(glessons($lang));$n=$lesson['number']-1;if($n>0):?><a class="button secondary" href="<?=gp($lang,$all[$n-1]['id'])?>">← <?=gh($u['previous'])?></a><?php endif;?><a class="button secondary" href="<?=gp($lang)?>"><?=gh($u['all'])?></a><?php if($n<11):?><a class="button" href="<?=gp($lang,$all[$n+1]['id'])?>"><?=gh($u['next'])?> →</a><?php endif;?></nav><?php gend($lang);}
